const app=document.querySelector('#app');let timer=null;let position=0;let currentTheme='minimal';
const designs={minimal:{label:'01 / MINIMAL',eyebrow:'Global Conflicts · Arma Reforger',title:'Good people.<br>Great operations.',description:'A community built around teamwork and tactical play. Find your squad. Make your next session count.',art:'THE BIG PICTURE / EVERY ROLE MATTERS'},field:{label:'02 / FIELD MANUAL',eyebrow:'Global Conflicts / Community operations',title:'One squad.<br>One objective.',description:'Tactical Arma Reforger. Shared objectives. People you can count on.',art:'FIELD STUDY 002 / OPERATIONS OVERVIEW'},signal:{label:'03 / SIGNAL',eyebrow:'Arma Reforger / Global Conflicts',title:'Find your<br>frequency.',description:'Different places. One shared mission. Connect with a community that plays together.',art:'TRANSMISSION OPEN / FIND YOUR SQUAD'}};
function terrain(units=true){return `<svg viewBox="0 0 600 440" role="img" aria-label="Illustrative tactical terrain map"><defs><pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="currentColor" opacity=".10"/></pattern></defs><rect width="600" height="440" fill="url(#grid)"/><g fill="none" stroke="currentColor" opacity=".18">${Array.from({length:8},(_,i)=>`<path d="M${-120+i*24} 440 Q${70+i*25} 300 ${10+i*28} 170 T${280+i*25} -40"/>`).join('')}<path d="M0 320Q180 240 230 290T600 200" stroke-width="25" opacity=".35"/><path d="M0 320Q180 240 230 290T600 200" stroke-width="2"/></g><g fill="currentColor" opacity=".13"><rect x="345" y="130" width="32" height="45" transform="rotate(20 345 130)"/><rect x="395" y="156" width="45" height="24"/><rect x="370" y="205" width="28" height="20"/></g><g id="routeLayer"><path d="M100 355L210 305L290 230L410 150" stroke="var(--accent)" stroke-width="2" stroke-dasharray="7 7" fill="none"/><circle cx="410" cy="150" r="40" fill="none" stroke="var(--accent)"/><path d="M410 135v30m-15-15h30" stroke="var(--accent)"/></g>${units?'<g id="unitLayer"><g id="squad" transform="translate(210 305)"><circle r="20" fill="var(--accent)" opacity=".15"/><circle r="6" fill="var(--accent)"/><text x="17" y="-13" font-size="11" fill="var(--ink)" font-family="monospace">ALPHA</text></g><g transform="translate(270 330)"><path d="M0-6L7 6H-7Z" fill="var(--accent)"/><text x="14" y="5" font-size="10" fill="var(--ink)" font-family="monospace">BRAVO</text></g></g>':''}</svg>`}
function orbit(){return `<svg viewBox="0 0 600 440" role="img" aria-label="Abstract radar connecting squad signals"><g fill="none" stroke="var(--accent)"><circle cx="300" cy="220" r="180" opacity=".2"/><circle cx="300" cy="220" r="130" opacity=".3"/><circle cx="300" cy="220" r="75" opacity=".5"/><ellipse cx="300" cy="220" rx="220" ry="75" transform="rotate(-32 300 220)"/><g class="orbital"><ellipse cx="300" cy="220" rx="220" ry="75" transform="rotate(35 300 220)" opacity=".35"/><circle cx="300" cy="40" r="6" fill="var(--accent)"/><path d="M300 40V400M120 220H480" opacity=".15"/></g><circle cx="300" cy="220" r="15" fill="var(--accent)"/></g><text x="325" y="211" fill="var(--ink)" font-size="12" font-family="monospace">YOU ARE HERE</text></svg>`}
function link(page,text,cls=''){return `<a class="${cls}" href="#${currentTheme}/${page}">${text}</a>`}
function render(){clearInterval(timer);timer=null;const parts=location.hash.slice(1).split('/');currentTheme=designs[parts[0]]?parts[0]:'minimal';const page=['home','operations','playback','join'].includes(parts[1])?parts[1]:'home';document.body.className=currentTheme;document.querySelectorAll('[data-theme]').forEach(a=>{a.classList.toggle('active',a.dataset.theme===currentTheme);a.href='#'+a.dataset.theme+'/'+page});const d=designs[currentTheme];app.innerHTML=`<header>${link('home','<span class="mark">GC</span><span>GLOBAL<br>CONFLICTS</span>','brand')}<nav aria-label="Main navigation">${link('home','Community')}${link('operations','Sessions')}${link('playback','Playback')}${link('join','Join us ↗','btn')}</nav></header><main>${page==='home'?home(d):page==='playback'?playback():page==='operations'?operations():join()}</main><footer><span>GLOBAL CONFLICTS / ${d.label}</span><span>Design concept · Arma Reforger</span><a href="https://globalconflicts.net/" target="_blank" rel="noopener">Original community site ↗</a></footer>`;document.querySelector(`nav a[href="#${currentTheme}/${page}"]`)?.setAttribute('aria-current','page');if(page==='playback')wirePlayer();document.title=`${d.label.slice(5)} — Global Conflicts`;}
function home(d){return `<section class="hero"><div><div class="eyebrow">${d.eyebrow}</div><h1>${d.title}</h1><p>${d.description}</p><div class="actions">${link('join','Join the community ↗','btn')}${link('playback','Explore playback →','btn secondary')}</div></div><div class="hero-art"><span class="coordinate">GC / ${currentTheme==='signal'?'CONNECTED':'TACTICAL STUDY'}</span>${currentTheme==='signal'?orbit():terrain()}<span class="art-label">${d.art}</span></div></section><section class="facts" aria-label="Community at a glance"><div class="fact"><div class="eyebrow">Who / What</div><h3>Tactical play. Good company.</h3><p>Teamwork, community-made missions, shared responsibility.</p></div><div class="fact"><div class="eyebrow">When</div><h3>Weekends · 19:00 UTC</h3><p>Reference schedule · confirm Reforger events with GC.</p></div><div class="fact"><div class="eyebrow">How</div><h3>Find GC. Get involved.</h3><p>A working microphone. A mature attitude. Your squad awaits.</p></div></section><section class="next"><div><div class="eyebrow">Beyond the operation</div><h2>Replay. Understand. Improve.</h2></div>${link('playback','Open the briefing demo ↗','text-link')}</section>`}
function operations(){return `<div class="page-heading"><div class="eyebrow">When we play</div><h1>Make room for your squad.</h1><p>GC’s published schedule is Saturday and Sunday at 19:00 UTC.<br>Confirm Reforger-specific sessions with the community before joining.</p></div><section class="schedule">${['Saturday','Sunday'].map(day=>`<article><div><span class="eyebrow">Weekly reference schedule</span><h2>${day}</h2></div><div><h2>19:00 UTC</h2><p>Check event details for current availability.</p></div>${link('join','How to join ↗','btn secondary')}</article>`).join('')}<a class="text-link" href="https://globalconflicts.net/" target="_blank" rel="noopener">Confirm on the community site ↗</a></section>`}
function join(){return `<div class="page-heading"><div class="eyebrow">Your next step</div><h1>Come play with us.</h1><p>A microphone, a mature attitude, and a willingness to work together.</p></div><section class="steps"><article class="step"><b>01 / CONNECT</b><h2>Meet the community.</h2><p>Visit GC’s current site for its Discord link, guides, and latest community information.</p><a class="btn" href="https://globalconflicts.net/" target="_blank" rel="noopener">Open Global Conflicts ↗</a></article><article class="step"><b>02 / PREPARE</b><h2>Get session-ready.</h2><p>Confirm the Reforger server, required mods, and event time with the community. Check your microphone.</p></article><article class="step"><b>03 / JOIN</b><h2>Find your squad.</h2><p>Follow the community’s server instructions, listen to the briefing, and work with your team.</p>${link('operations','See the reference schedule →','text-link')}</article></section>`}
function playback(){return `<div class="page-heading"><div class="eyebrow">Playback lab / simulated briefing</div><h1>See the whole operation.</h1><p>Operation Pine / fictional scenario · Explore a future briefing workspace.</p></div><section class="workspace" aria-label="Briefing player"><aside class="sidebar"><div class="eyebrow">Chapters</div><button data-time="0">01 &nbsp; Situation</button><button data-time="35">02 &nbsp; Approach</button><button data-time="70">03 &nbsp; Objective</button><button data-time="100">04 &nbsp; Debrief</button></aside><div class="map">${terrain()}<span class="map-caption">ILLUSTRATIVE TERRAIN / NOT GAME DATA</span></div><aside class="intel"><div><div class="eyebrow">Briefing notes</div><h3 id="chapterTitle">Situation</h3><p id="chapterNote"></p></div><div><div class="eyebrow">Map layers</div><label><input type="checkbox" checked id="units"> Squad positions</label><label><input type="checkbox" checked id="routes"> Planned route</label></div></aside></section><div class="timeline"><button id="play" aria-label="Play simulated briefing">▶ Play</button><output id="time">00:00 / 02:00</output><input aria-label="Playback position" id="scrub" type="range" min="0" max="120" value="0"><select id="speed" aria-label="Playback speed"><option value="1">1× speed</option><option value="2">2× speed</option><option value="4">4× speed</option></select><button id="reset">↺ Reset</button></div><p class="demo-note">Interactive concept: playback, scrubbing, chapters, speed, and layers work with simulated data. Live recordings and game integration are future work.</p>`}
function wirePlayer(){position=0;const notes=['Alpha and Bravo assemble southwest of the objective. Review the planned approach.','Alpha advances along the marked route. Bravo holds the southern approach.','Alpha reaches the objective area. Coordinate the final approach with Bravo.','Review squad movement and timing. Use the timeline to revisit key moments.'];function update(){document.querySelector('#scrub').value=position;document.querySelector('#time').textContent=`${String(Math.floor(position/60)).padStart(2,'0')}:${String(Math.floor(position%60)).padStart(2,'0')} / 02:00`;let idx=position<35?0:position<70?1:position<100?2:3;document.querySelector('#chapterTitle').textContent=['Situation','Approach','Objective','Debrief'][idx];document.querySelector('#chapterNote').textContent=notes[idx];document.querySelectorAll('[data-time]').forEach((b,i)=>b.classList.toggle('selected',i===idx));document.querySelector('#squad').setAttribute('transform',`translate(${100+position*2.58} ${355-position*1.7})`)}function stop(){clearInterval(timer);timer=null;document.querySelector('#play').textContent='▶ Play';document.querySelector('#play').setAttribute('aria-label','Play simulated briefing')}document.querySelector('#play').onclick=()=>{if(timer){stop();return}if(position>=120)position=0;document.querySelector('#play').textContent='Ⅱ Pause';document.querySelector('#play').setAttribute('aria-label','Pause simulated briefing');timer=setInterval(()=>{position=Math.min(120,position+.25*Number(document.querySelector('#speed').value));update();if(position>=120)stop()},250)};document.querySelector('#scrub').oninput=e=>{position=Number(e.target.value);update()};document.querySelectorAll('[data-time]').forEach(b=>b.onclick=()=>{position=Number(b.dataset.time);update()});document.querySelector('#reset').onclick=()=>{stop();position=0;update()};document.querySelector('#units').onchange=e=>document.querySelector('#unitLayer').style.display=e.target.checked?'':'none';document.querySelector('#routes').onchange=e=>document.querySelector('#routeLayer').style.display=e.target.checked?'':'none';update()}
window.addEventListener('hashchange',render);render();
